-- Mauritania fourth preparatory year (mapped grade 10): 43 original
-- supplementary exercises across existing official-import title stubs.
-- Independent educational prose; all ministry/source matching is pending.
DO $dadyoom$
DECLARE r RECORD; target_id uuid; prior text; nact integer; hasprogress integer;
BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset('[{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"a7c42740-fde8-492f-ae19-009042b22686","n":1,"title":"شبكات التواصل الاجتماعي","passage":"تتيح شبكات التواصل مشاركة الأفكار والمواد بسرعة، لكن انتشار المنشور ليس دليلًا على صحته، كما تتطلب المشاركة احترام الخصوصية. في نموذج مستقل يراجع طالب مصدر إعلان مدرسي وتاريخه قبل إعادة نشره.","question":"ما الإجراء المناسب قبل إعادة نشر منشور؟","correct":"التحقق من المصدر والتاريخ","wrong":["الاكتفاء بعدد الإعجابات","نقل خبر مجهول","إخفاء أصل الخبر"],"practice":"اكتب بطاقة تحقق من منشور عامة مع المصدر والادعاء والقرينة.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"a7c42740-fde8-492f-ae19-009042b22686","n":2,"title":"الإعلام بين الإخبار والتأثير","passage":"ينقل الخبر واقعة قابلة للتحقق، بينما تسعى المقالات والحملات أحيانًا إلى تشكيل موقف القارئ عبر الانتقاء والصورة والعنوان. لا يعني ذلك أن كل تأثير غير مشروع؛ نفصل بين الدليل والرأي والإعلان. مثال أصلي يقدم حدث معرض ثم تعليقًا عليه.","question":"ما الفرق الأساسي بين الخبر والتعليق في المثال؟","correct":"الخبر يقرر الواقعة والتعليق يفسرها أو يقوّمها","wrong":["الخبر بلا مصدر دائمًا","التعليق رقم فقط","هما واحد تمامًا"],"practice":"قارن خبرًا ورأيًا موثقين عن موضوع واحد، وحدد كيف يظهر التأثير في اللغة.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"f8fb9244-84c7-422c-9ba8-4e221ef811f1","n":1,"title":"المقابلة","passage":"المقابلة تجمع معنيين أو أكثر ثم ما يقابلها مع ترتيب مناسب، وقد تبرز التباين وتقوي التعبير. لا يعد كل اختلاف بين كلمتين مقابلة بلاغية. في نموذج مستقل تتجاور صور النجاح والإخفاق مع الأسباب لإبراز المقارنة.","question":"ما الذي يميز المقابلة؟","correct":"تقابل مجموعتين من المعاني بترتيب","wrong":["اشتقاق من جذر واحد","تكرار الوزن","السؤال عن الزمن"],"practice":"ابحث عن مقابلة صحيحة في مصدر بلاغي ثم بيّن العناصر المتقابلة.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"f8fb9244-84c7-422c-9ba8-4e221ef811f1","n":2,"title":"الجناس","passage":"الجناس تشابه اللفظين مع اختلاف المعنى، وتتنوع صوره بحسب اكتمال التشابه في الحروف والترتيب والحركات. يحتاج التحليل إلى معنى الكلمتين في السياق ولا يكفي أن تنتهيا بالحرف نفسه.","question":"ما العنصر الأساسي في الجناس؟","correct":"تشابه اللفظ مع اختلاف المعنى","wrong":["تضاد المعنى وحده","ترادف الكلمتين","تطابق الصور"],"practice":"اختر مثالًا للجناس من مرجع أدبي موثوق واشرح المعنيين ونوع التشابه.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"f8fb9244-84c7-422c-9ba8-4e221ef811f1","n":3,"title":"الطباق","passage":"الطباق اجتماع لفظين متضادين في المعنى ضمن سياق مثل «الليل والنهار»، وقد يقوي الفرق الذي يريده المتكلم. ليس كل زوج من الكلمات المختلفة طباقًا ما لم يظهر التضاد.","question":"أي زوج فيه طباق؟","correct":"الليل والنهار","wrong":["كتاب وقلم","بيت ومدرسة","طاولة وكرسي"],"practice":"اكتب أربعة أمثلة للطباق واشرح أثر التضاد في واحد منها.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"ed7fca3d-566d-44eb-89f3-a0acb5870e1f","n":1,"title":"العولمة والثقافة","passage":"يتبادل الناس الأفكار والمنتجات عبر شبكات عالمية، وقد يوفر ذلك فرصًا للتعلم مع تحديات تتصل بالتنوع والخصوصية والوصول العادل. في مثال مستقل يتعاون طلاب من مدن مختلفة على مشروع قراءة ويحتاجون إلى توثيق ترجمة المصطلحات.","question":"ما الخطوة التي تحسّن تعاون طلاب مختلفي اللغات؟","correct":"توضيح المعاني والاحترام المتبادل","wrong":["افتراض تطابق الثقافات","إلغاء الترجمة","السخرية من الاختلاف"],"practice":"اكتب فقرة متوازنة عن فرصة وتحدٍّ في التواصل الثقافي العالمي.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"ed7fca3d-566d-44eb-89f3-a0acb5870e1f","n":2,"title":"الأصالة والمعاصرة","passage":"يمكن للأدب المعاصر أن يحافظ على عناصر لغوية أو فنية موروثة ويطور موضوعًا أو بناءً جديدًا؛ لا تعني الأصالة رفض كل جديد ولا تعني المعاصرة محو الماضي. في مثال أصلي يعيد فريق تقديم حكاية قديمة بلغة مفهومة مع توثيق المصدر.","question":"ما التصرف الذي يجمع الأصالة والتجديد في المثال؟","correct":"توثيق الحكاية وإعادة عرضها بأسلوب جديد","wrong":["إخفاء الأصل","رفض كل تطوير","نسخ النص دون ذكر مصدر"],"practice":"قارن نصًا تراثيًا مأذونًا ومعالجة معاصرة مع بيان ما استمر وما تغير.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"ed7fca3d-566d-44eb-89f3-a0acb5870e1f","n":3,"title":"ثقافة القراءة","passage":"تقوم ثقافة القراءة على الوصول إلى مواد متنوعة وتبادل الأفكار وتحليل المصادر، لا مجرد شراء كتب كثيرة. في مثال مستقل يجتمع القراء أسبوعيًا لتفسير فقرة وتقديم شاهد يدعم رأيهم.","question":"ما السلوك الذي يدل على قراءة نقدية؟","correct":"تفسير فكرة ومناقشتها بدليل","wrong":["عد الكتب دون قراءة","نسخ العنوان فقط","تجنب السؤال"],"practice":"صمم نشاط نادي قراءة فيه فكرة وسؤال ودليل ومراجعة.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"b712b938-6c99-4090-ab6c-3f2a0315ae53","n":1,"title":"إيليا أبو ماضي","passage":"تستلزم دراسة شعر إيليا أبي ماضي نصًا صحيح النسبة قبل تحديد النزعة الوجدانية والصور أو الرسالة، ولا يجوز اختلاق بيت على لسانه. مثال مستقل يصف راو غربةً وحنينًا لمكان قديم، ويمثل تمرينًا على الصورة فقط.","question":"ما الدليل المناسب على عاطفة شعرية عند إيليا أبي ماضي؟","correct":"شواهد موثقة من قصيدته","wrong":["اسمه وحده","مقطع مولد","عنوان درس فقط"],"practice":"استخرج بيتًا حقيقيًا وصورة ووضح أثرهما في عاطفة النص.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"b712b938-6c99-4090-ab6c-3f2a0315ae53","n":2,"title":"معروف الرصافي","passage":"لا يكفي اسم معروف الرصافي لتحديد موقف سياسي أو اجتماعي أو صورة فنية في قصيدة بعينها، بل يلزم نصه المدرسي الموثق. نموذج مستقل يعرض راو مشكلة تعليمية ويدعو إلى مناقشتها دون نسبة القول للشاعر.","question":"ما الخطوة الصحيحة قبل وصف غرض القصيدة؟","correct":"قراءة الأبيات الموثقة ومقامها","wrong":["تخمين غرض من اسم الشاعر","اختلاق أبيات","الاستناد إلى لقبه"],"practice":"حلل نصًا صحيحًا للرصافي مبينًا الفكرة وأداة تصويرية.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"b712b938-6c99-4090-ab6c-3f2a0315ae53","n":3,"title":"علي محمود طه","passage":"يحتاج شعر علي محمود طه إلى نص مقرر موثق لتحديد طبيعة الصور والإيقاع والتجربة، ولا يصح افتراض أن كل شعره على موضوع واحد. مثال مستقل يصور متكلمًا انعكاس القمر في الماء دون نسبته إليه.","question":"ما الذي يثبت ملاءمة صورة الطبيعة للعاطفة؟","correct":"ترابط الألفاظ والصور داخل الأبيات الصحيحة","wrong":["اسم الشاعر وحده","عنوان عام","تفسير بلا نص"],"practice":"وثق صورة من القصيدة المقررة واشرح كيف خدمت معنى المقطع.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"d5136a97-abd6-432a-b1d4-d0de2c5b7a9e","n":1,"title":"أبو القاسم الشابي","passage":"تحليل قصيدة لأبي القاسم الشابي يتطلب نصها المعتمد لمعرفة المخاطب وإيقاع الأمل أو القلق، ولا يجوز تأليف أبيات أو روايات عن حياته. المثال الأصلي لمتعلم يراجع تجربة صعبة ويحتفظ بالأمل في تغيير منهجه.","question":"ما الذي يمنع نسبة معنى محدد للشاعر بلا دليل؟","correct":"ضرورة الرجوع إلى الأبيات الصحيحة","wrong":["العنوان وحده","صورة من إنشائنا","الاعتماد على الانطباع"],"practice":"استخرج صورة وقرينة عاطفية من قصيدة صحيحة للشابي مع التوثيق.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"d5136a97-abd6-432a-b1d4-d0de2c5b7a9e","n":2,"title":"محمود درويش","passage":"يحتاج شعر محمود درويش إلى النص المعتمد والسياق الأدبي لتحديد دلالات الوطن والذاكرة أو الذات في القصيدة المختارة، ولا يصح توليد أبيات منسوبة إليه. في نموذج أصلي يحتفظ مسافر بمفتاح منزل قديم بوصفه رمزًا للذكرى.","question":"ما الذي يحدد وظيفة الرمز في قصيدة حقيقية؟","correct":"وروده وسياقه وصوره في النص الموثق","wrong":["اسم الشاعر وحده","بيت مختلق","أحداث بلا مرجع"],"practice":"اختر شاهدًا صحيحًا مأذونًا من قصيدة مقررة وناقش صورة ورمزًا.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"52fbce63-1114-47e3-a32b-2020c1536bfb","n":1,"title":"القصة القصيرة","passage":"تتكون القصة القصيرة من حدث أو موقف وشخصيات وتوتر وتغير، وتحتاج وحدة البناء إلى أن يخدم التفصيل محور القصة. مثال مستقل ينسى طالب موعد تسليم ثم يتدارك الخطأ بالتواصل المبكر، فتتطور الحكاية بفعل اختياراته.","question":"ما العنصر الذي ربط النهاية بالعقدة في المثال؟","correct":"تصرف الشخصية لإصلاح الخطأ","wrong":["مصادفة بلا سبب","تغيير اسم المكان","حذف كل الأحداث"],"practice":"اكتب مخطط قصة بثلاثة مشاهد وعقدة وحل يرتبط بالسبب.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"52fbce63-1114-47e3-a32b-2020c1536bfb","n":2,"title":"السيرة الذاتية","passage":"تنقل السيرة الذاتية تجربة يرويها صاحبها وفق ذاكرته واختيار الأحداث، ويُفرق بين الواقع الموثق وإعادة بناء المشاهد في الكتابة. في نموذج مستقل يكتب طالب ذكرى تعلمه القراءة ويذكر ما يستطيع التحقق منه وما بقي انطباعًا.","question":"ما السمة الأهم للراوي في السيرة الذاتية؟","correct":"تحدثه عن تجربته من وجهة نظره","wrong":["كونه راويًا عليمًا دائمًا","غياب الزمن","انعدام الشخصيات"],"practice":"اكتب ذكرى شخصية آمنة من خمس جمل مع فصل الحدث عن شعورك تجاهه.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"52fbce63-1114-47e3-a32b-2020c1536bfb","n":3,"title":"المسرحية","passage":"تُظهر المسرحية الصراع عبر حوار وأفعال الشخصيات وإرشادات الأداء، وقد يختلف المعنى بإيقاع التفاعل والحركة. في مثال مستقل يختلف طالبان حول تنظيم معرض ثم يتفقان على خطة مشتركة بعد مناقشة الأدلة.","question":"ما العنصر الذي يدفع المشهد المسرحي إلى التطور؟","correct":"الحوار والفعل الذي يغير المواقف","wrong":["الوزن الشعري وحده","سرد بلا شخصيات","إلغاء الزمن"],"practice":"حوّل قصة صغيرة إلى مشهد من شخصيتين يتضمن إرشادات مسرحية.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"d372ce92-3752-446e-a6c4-434a82003342","n":1,"title":"الزواج (الزواج المبكر، اختيار الشريك، شروط الزواج، الزواج والعمل)","passage":"تناقش هذه الموضوعات من زاوية الحقوق والرضا الناضج وسلامة الأفراد والتعليم والمسؤولية الأسرية، مع مراعاة أن القوانين والأعمار المحددة تختلف باختلاف الدولة. يجب تجنب تبرير زواج الأطفال، وتحتاج الأحكام القانونية أو الدينية إلى مصدر محلي موثوق.","question":"ما الذي يجب مراعاته عند تناول الزواج المبكر تربويًا؟","correct":"حماية القاصرين وحقوقهم والتعليم والسلامة","wrong":["إلغاء رضا الأطراف","تجاهل القوانين","افتراض جاهزية كل طفل"],"practice":"اكتب تحليلًا متزنًا يستند إلى مصدر حقوقي موثوق ويتجنب إصدار فتوى أو حكم قانوني غير مثبت.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"d372ce92-3752-446e-a6c4-434a82003342","n":2,"title":"التضامن الاجتماعي","passage":"قد يتمثل التضامن الاجتماعي في دعم متبادل منظم يحترم كرامة المستفيدين وخصوصيتهم؛ ولا تعني المساعدة كشف بيانات الأشخاص أو افتراض احتياجاتهم دون سؤال. في مثال مستقل يشارك طلاب في توفير كتب مكتبة عامة بإذن الجهة.","question":"ما المبدأ الذي يجعل المساعدة أكثر احترامًا؟","correct":"الحفاظ على الكرامة والخصوصية","wrong":["نشر أسماء المحتاجين","فرض المساعدة","إخفاء الغاية"],"practice":"صمم مبادرة دعم تعليمية مع إجراءات حماية الخصوصية ومؤشر للنتيجة.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"d372ce92-3752-446e-a6c4-434a82003342","n":3,"title":"هجرة العقول","passage":"يشير مصطلح هجرة العقول إلى انتقال أشخاص ذوي خبرات ومهارات بين مناطق أو دول، وله أسباب اقتصادية وعلمية وشخصية متباينة، ولا يصح تعميم دافع واحد على الجميع. مثال مستقل يقارن باحث فرص تدريب بين بلدين ويقيس مزايا وظروف كل خيار.","question":"ما المنهج المناسب لفهم دوافع الهجرة؟","correct":"جمع مصادر ووجهات نظر متعددة","wrong":["اتهام جميع المهاجرين","تعميم قصة فرد واحد","اختلاق نسب"],"practice":"اكتب مقارنة حول عاملين محتملين للهجرة مع مصادر وحدود الاستنتاج.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"46fa404b-9dd2-43d8-9977-cf4fefc43027","n":1,"title":"الثروة الحيوانية","passage":"تختلف موارد الثروة الحيوانية باختلاف المناخ والمياه والرعي والخدمات البيطرية، وتتطلب بيانات إحصائية محلية لفهم الإنتاج والتحديات. في مثال مستقل يناقش فريق أهمية حفظ سجلات صحة الحيوانات من جهات مختصة دون تقديم علاج بيطري.","question":"ما الذي يسبق تقييم موارد الثروة الحيوانية؟","correct":"بيانات موثوقة عن البيئة والقطيع والإنتاج","wrong":["تخمين الأعداد","تجاهل الماء","إلغاء المصدر"],"practice":"اكتب فقرة عن مورد حيواني موثق مع فائدته وتحدٍ بيئي.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"46fa404b-9dd2-43d8-9977-cf4fefc43027","n":2,"title":"الفساد وأثره على الاقتصاد","passage":"قد يضعف الفساد الثقة وعدالة التنافس وجودة الخدمات عندما تُستخدم السلطة أو الموارد لمنافع غير مشروعة، لكن إثبات حالة بعينها يحتاج أدلة وإجراءات قانونية لا اتهامات. في مثال مستقل تضع لجنة معايير شراء معلنة ومراجعة مستقلة.","question":"ما الذي يقلل فرص تضارب المصالح في المثال؟","correct":"شفافية المعايير ومراجعة القرار","wrong":["الشراء دون سجل","إخفاء الأسعار","اتهام بلا دليل"],"practice":"حلل نموذج سياسة شفافية عامة مع سبب وآلية محاسبة دون اتهام أشخاص.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"dd6ed2f8-5e3d-42a2-af5a-705fc36e1aaf","n":1,"title":"خطر النفايات على البيئة","passage":"يمكن أن تؤثر النفايات في التربة والمياه والحياة البرية بحسب نوعها وطريقة إدارتها، وتتطلب تقييمات الأثر بيانات علمية لا صورًا وحدها. في مثال مستقل يفصل فريق مواد قابلة للتدوير بإرشاد مختص ويتجنب لمس نفايات مجهولة.","question":"ما السلوك الآمن عند العثور على مخلفات مجهولة؟","correct":"إبلاغ الجهة المختصة وعدم لمسها","wrong":["حملها دون حماية","نشر تخمين","إلقاؤها في الماء"],"practice":"اكتب تقريرًا قصيرًا يميز الملاحظة من النتيجة العلمية في إدارة النفايات.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"dd6ed2f8-5e3d-42a2-af5a-705fc36e1aaf","n":2,"title":"انحسار الغطاء النباتي","passage":"يتصل تغير الغطاء النباتي بعوامل متعددة مثل المناخ واستعمال الأراضي والماء والحرائق، وتتطلب معرفة سبب منطقة معينة بيانات زمنية ومكانية. في مثال مستقل يقارن الطلاب صورًا مؤرخة لمنطقة بعد الحصول على مصدرها.","question":"ما الدليل الأفضل على انحسار غطاء نباتي بموقع معين؟","correct":"قياسات أو صور موثقة عبر زمن محدد","wrong":["لقطة واحدة دون تاريخ","تخمين سبب واحد","حكاية مجهولة"],"practice":"حلل بيانات بيئية موثوقة وحدد ما يمكن وما لا يمكن استنتاجه.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"dd6ed2f8-5e3d-42a2-af5a-705fc36e1aaf","n":3,"title":"الاهتمام العالمي بالبيئة","passage":"قد تتعاون الجهات المحلية والدولية في قضايا بيئية تتجاوز الحدود، لكن أثر أي مبادرة يحتاج أهدافًا ومؤشرات ومصادر مستقلة. في مثال مستقل تشارك مدارس متعددة في مشروع لتقليل الهدر وتعلن ما قاسوه لا ما يتوقعونه.","question":"ما الذي يسمح بتقويم حملة بيئية؟","correct":"مؤشرات قابلة للقياس ومصادر معلنة","wrong":["الشعار وحده","عدد الملصقات دون أثر","اختلاق النتائج"],"practice":"اكتب خطة مبادرة بيئية مع أهداف قابلة للتحقق.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"e9c09d13-546a-4c30-b511-45d2a1a75694","n":1,"title":"كأس العالم","passage":"تتغير نتائج كأس العالم ومواعيد نسخه عبر الزمن وتحتاج الإشارة إلى سنة ومسابقة محددتين ومصدر رياضي رسمي، ولا يجوز اختلاق الفرق والنتائج. في مثال مستقل يقارن طالب تقريرين عن بطولة ويلاحظ اختلاف سنة الإحصاء.","question":"ما الذي يلزم لتوثيق نتيجة مباراة في كأس العالم؟","correct":"سنة المسابقة وسجل رسمي للمباراة","wrong":["رأي مشجع","حكاية مجهولة","عنوان الخبر وحده"],"practice":"اكتب تقريرًا تاريخيًا قصيرًا عن نسخة محددة مع مصادر دقيقة.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"e9c09d13-546a-4c30-b511-45d2a1a75694","n":2,"title":"الرياضة والإعلام","passage":"يسهم الإعلام في نقل المباريات وصناعة القصص الرياضية، لكنه قد يخلط أحيانًا الوقائع بالتعليق أو يركز على لقطات محددة. في مثال مستقل يقارن طالب بين جدول النتائج ومقطع رأي رياضي ويذكر وظيفة كل منهما.","question":"أي عنصر يمثل معلومة قابلة للتحقق أكثر من تعليق؟","correct":"النتيجة الواردة في سجل المباراة الرسمي","wrong":["الانطباع عن الأداء","وصف اللاعب بأنه الأفضل","شعار القناة"],"practice":"حلل خبرًا رياضيًا وتعليقًا عن حدث واحد مع فصل البيانات عن الرأي.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"e9c09d13-546a-4c30-b511-45d2a1a75694","n":3,"title":"الرياضة والمنشطات","passage":"تتعلق مكافحة المنشطات بالنزاهة والصحة ولوائح الهيئات الرياضية ذات الصلة، ولا يصح الحكم على رياضي بعينه دون قرار موثق. تجنب النصوص التي توضح استعمال المواد المحظورة؛ ركز على السلامة والمسؤولية والمصادر الرسمية.","question":"ما الأساس الصحيح للتحقق من مخالفة منشطات محددة؟","correct":"قرار وإجراء موثقان من جهة مختصة","wrong":["إشاعة","صورة بلا مصدر","تخمين الأداء"],"practice":"اكتب نصًا عن نزاهة المنافسة دون ذكر طرق تعاطي أو اتهام أشخاص.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"7e176afc-7f08-42c5-aa22-9b03ec55c703","n":1,"title":"التغذية والصحة","passage":"تختلف الاحتياجات الغذائية باختلاف العمر والنشاط والحالة الصحية، ولا تصلح فقرة عامة لإعطاء نظام علاجي فردي. في مثال مستقل يقرأ طالب بطاقة منتج ليفهم المكونات والتاريخ ثم يرجع لجهة صحية معتمدة بشأن الادعاءات.","question":"ما الذي يجعل معلومات غذائية عامة أكثر موثوقية؟","correct":"مصدر صحي معتمد وبيانات واضحة","wrong":["نصيحة مجهولة","دعاية وحدها","حكاية فردية"],"practice":"اكتب فقرة معلوماتية عن قراءة الملصق الغذائي دون اقتراح حمية علاجية.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"7e176afc-7f08-42c5-aa22-9b03ec55c703","n":2,"title":"الوقاية من الأمراض","passage":"تعتمد إجراءات الوقاية من الأمراض على نوع العامل المسبب وطرق انتقاله وتوصيات الجهات الصحية المعتمدة، لذلك لا توجد نصيحة واحدة تكفي لكل الأمراض. في نموذج مستقل تسأل مدرسة الجهة الصحية عن إرشادات ملائمة بدل الاعتماد على شائعة.","question":"ما مصدر الإرشاد الأنسب للوقاية في سياق معين؟","correct":"جهة صحية موثوقة وتوصيات محدثة","wrong":["منشور مجهول","تخمين شخصي","قصة غير مؤكدة"],"practice":"حلل منشورًا وقائيًا من مصدر رسمي وحدد الفئة المستهدفة وحدود نصيحته.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"7e176afc-7f08-42c5-aa22-9b03ec55c703","n":3,"title":"تطور الأساليب الطبية","passage":"تعكس الأساليب الطبية تغير الأدلة والأدوات والتجارب عبر الزمن، ولا يجوز اعتبار علاج تاريخي صالحًا اليوم لمجرد شهرته. في مثال مستقل يقارن طالب أداة تشخيص قديمة بأخرى حديثة من مصدر علمي دون تقديم رأي علاجي.","question":"ما الذي يضبط مقارنة علاج أو أداة عبر العصور؟","correct":"الدليل العلمي وسياق الاستعمال","wrong":["الشهرة وحدها","الاسم القديم","حكاية مجهولة"],"practice":"اكتب تقريرًا عن تطور وسيلة طبية موثقة يفصل التاريخ عن الممارسة الحديثة.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"9edd2029-409c-4d7b-a3e3-2af6badf6b09","n":1,"title":"الطاقة النظيفة","passage":"تُناقش طاقة أقل تلويثًا بمقارنة الانبعاثات ودورة حياة التقنيات والموارد والبيئة المحلية، ولا يعني وصف «نظيف» انعدام كل أثر بيئي. في مثال مستقل يقارن فريق خيارين لإضاءة مدرسة ويبحث عن بيانات دورة الحياة.","question":"ما الذي يمنع التعميم بأن مصدرًا لا أثر له مطلقًا؟","correct":"مراعاة دورة الحياة والآثار المتنوعة","wrong":["الاكتفاء بالاسم التسويقي","إلغاء القياس","تجاهل التصنيع"],"practice":"اكتب مقارنة بين مصدرين للطاقة مع ميزة وقيد ومرجع موثوق.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"9edd2029-409c-4d7b-a3e3-2af6badf6b09","n":2,"title":"الآلة والإنسان","passage":"يمكن للأدوات والآلات أن تساعد البشر في أعمال عديدة، لكن تصميمها واستخدامها يثيران مسائل السلامة والمهارات والعمل والإنصاف. في مثال مستقل يستخدم طالب أداة رقمية لتلخيص ملاحظاته ثم يتحقق بنفسه من التفاصيل.","question":"ما السلوك الذي يحافظ على مسؤولية الإنسان عند استخدام آلة؟","correct":"مراجعة النتائج وفهم حدود الأداة","wrong":["الثقة العمياء","إخفاء الخطأ","إلغاء الإشراف"],"practice":"اكتب فقرة عن مهمة تفيد فيها آلة وأخرى تحتاج حكمًا بشريًا مع سبب.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"9edd2029-409c-4d7b-a3e3-2af6badf6b09","n":3,"title":"غزو الفضاء","passage":"تحتاج أخبار الاستكشاف الفضائي إلى التحقق من الجهة والمهمة وتاريخ الإطلاق والنتائج، ولا تثبت صورة واحدة صلاحية ادعاء علمي كبير. في مثال مستقل يراجع طالب صفحة وكالة فضاء رسمية قبل عرض معلومات عن بعثة.","question":"ما الذي يوثق ادعاء عن بعثة فضائية؟","correct":"بيانات المهمة من جهة علمية موثوقة","wrong":["فيديو مجهول","صورة دون تاريخ","تخمين"],"practice":"اختر مهمة فضائية موثقة واكتب وصفًا لهدفها وما تحقق منها دون اختلاق.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"1bd2c3ec-1ec6-406c-b7da-d8a111b63a38","n":1,"title":"احترام الآخر","passage":"يشمل احترام الآخر الإنصات والامتناع عن التحقير وحماية الحقوق مع إمكان الاختلاف في الآراء. في مثال مستقل يناقش طالبان اختيار كتاب دون الاتفاق على التقييم ثم يقدمان أسبابًا ويحفظان الاحترام.","question":"ما الممارسة التي تظهر الاحترام مع الاختلاف؟","correct":"عرض الحجة دون إهانة الشخص","wrong":["السخرية","الإقصاء بلا سبب","إخفاء الأسئلة"],"practice":"اكتب حوارًا يحترم رأيين مختلفين مع قاعدة للنقاش.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"1bd2c3ec-1ec6-406c-b7da-d8a111b63a38","n":2,"title":"السلم والحرب في عالمنا المعاصر","passage":"تستلزم دراسة النزاعات المعاصرة مصادر موثوقة ووعيًا بحماية المدنيين وحقوق الإنسان، مع التفريق بين التحليل الإعلامي والدعوة للعنف. في مثال مستقل يدعو طلاب إلى حوار وتضامن إنساني واحترام القانون الإنساني الدولي دون ادعاء حقائق عن نزاع معين.","question":"ما الإجراء الذي يعكس اهتمامًا بسلامة المدنيين؟","correct":"دعم الحماية الإنسانية والحوار السلمي","wrong":["التحريض على الأذى","نشر روايات غير مثبتة","إلغاء حقوق الأشخاص"],"practice":"حلل خطابًا عامًا عن السلام بمصادر موثوقة وميز الحجة عن الشعارات.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"1bd2c3ec-1ec6-406c-b7da-d8a111b63a38","n":3,"title":"دور المجتمع المدني في التنمية","passage":"قد يسهم المجتمع المدني في التعليم والتوعية والخدمات والمناصرة المشروعة عبر مبادرات مختلفة، ويتوقف أثر كل مبادرة على مواردها ومؤشرات نتائجها. في مثال مستقل تنظم جمعية قراءة عامة وتسجل المشاركة مع حفظ الخصوصية.","question":"ما الذي يساعد على تقييم مساهمة جمعية مدنية؟","correct":"هدف ومؤشر نتائج قابل للتحقق","wrong":["الشعار وحده","إخفاء الأنشطة","افتراض النجاح"],"practice":"صمم مشروعًا مدنيًا تعليميًا افتراضيًا مع مؤشر قياس وأخلاقيات خصوصية.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"d4a8c63a-67a5-4ab0-bd64-1d645c5e6d4d","n":1,"title":"مصادر الأفعال المجردة (الثلاثية والرباعية)","passage":"قد يأتي مصدر الفعل الثلاثي على أوزان سماعية مختلفة مثل «كتب كتابةً»، بينما مصدر الفعل الرباعي المجرد «دحرج» على «دحرجة» في القياس المذكور. يجب مراجعة المعجم لمعرفة المصدر الصحيح للفعل الثلاثي بدل فرض وزن واحد.","question":"ما مصدر «دحرج» في المثال؟","correct":"دحرجة","wrong":["دحراج","دحروج","مدحرج"],"practice":"اكتب مصادر خمسة أفعال ثلاثية وفعلين رباعيين مع المصدر المعجمي.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"d4a8c63a-67a5-4ab0-bd64-1d645c5e6d4d","n":2,"title":"مصادر الأفعال المزيدة","passage":"تتصل مصادر الأفعال المزيدة بأبنيتها الصرفية؛ مثل «أكرم إكرامًا» في مصدر صيغة أفعل، و«استخرج استخراجًا» في صيغة استفعل. يحتاج التحقق إلى تمييز الأصل وحروف الزيادة والحركات.","question":"ما مصدر «استخرج»؟","correct":"استخراج","wrong":["خرج","مخرج","خارِج"],"practice":"اشتق مصادر ستة أفعال مزيدة، واذكر البنية والزيادة.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"d4a8c63a-67a5-4ab0-bd64-1d645c5e6d4d","n":3,"title":"معاني صيغ الفعل المزيد","passage":"قد تفيد زيادة الحروف دلالات مثل التعدية أو المشاركة أو الطلب بحسب الفعل والسياق؛ فـ«علّم» بتضعيف العين قد يفيد التعدية من «علم» في تركيب مناسب، لكن لا تطرد دلالة واحدة لكل وزن.","question":"ما الذي يلزم لفهم دلالة صيغة المزيد؟","correct":"مقارنة المعنى في السياق مع الأصل","wrong":["عد الحروف فقط","الاعتماد على وزن دون معنى","مكان الكلمة"],"practice":"قارن أربعة أفعال مجردة ومزيدة واكتب فرق المعنى في جمل.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"d4a8c63a-67a5-4ab0-bd64-1d645c5e6d4d","n":4,"title":"المدح والذم (بئس ونعم)","passage":"«نِعْمَ» فعل جامد للمدح و«بِئْسَ» فعل جامد للذم، ويُدرس فاعلهما والمخصوص بالمدح أو الذم وفق القاعدة. في «نعم الخلقُ الأمانةُ» تحمل الجملة مدحًا للأمانة، ويحتاج الضبط إلى التحليل.","question":"ما فعل المدح في «نعم الخلق الأمانة»؟","correct":"نِعْمَ","wrong":["بِئْسَ","ليس","لم"],"practice":"أعرب مثالًا صحيحًا للمدح وآخر للذم مع تحديد المخصوص.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"d4a8c63a-67a5-4ab0-bd64-1d645c5e6d4d","n":5,"title":"التصغير","passage":"التصغير تغيير صرفي في بناء الاسم لأغراض قد تشمل بيان صغر الحجم أو التقليل أو التحبب بحسب السياق، مثل «كُتَيِّب» تصغير «كتاب» في استعمال معروف. لا تعني صيغة التصغير سخرية دائمًا.","question":"ما الأصل الذي صُغّر إلى «كُتَيِّب»؟","correct":"كتاب","wrong":["كاتب","مكتبة","كتابة"],"practice":"صغ خمسة أسماء تصغيرًا صحيحًا واشرح الغرض في جملة لكل منها.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"d4a8c63a-67a5-4ab0-bd64-1d645c5e6d4d","n":6,"title":"الأدوات المحددة لأزمنة الأفعال","passage":"تساعد أدوات مثل «سوف» على توجيه الفعل المضارع إلى المستقبل في «سوف يكتبُ»، بينما «لم» تنفي المضارع وتجزمه بدلالة زمنية مناسبة. يتحدد الزمن أيضًا من المقام والقرائن لا الأداة وحدها.","question":"ما الأداة التي تشير إلى المستقبل في «سوف يكتب»؟","correct":"سوف","wrong":["لم","لن وحدها في كل سياق","ليس"],"practice":"حوّل ثلاث جمل بين أزمنة مختلفة باستعمال قرائن وأدوات صحيحة.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"d4a8c63a-67a5-4ab0-bd64-1d645c5e6d4d","n":7,"title":"النسبة","passage":"يتكون اسم النسبة بإضافة ياء مشددة إلى الاسم مع تغييرات صرفية عند الحاجة، مثل «وطنِيّ» من «وطن». يستعمل في النعت والتصنيف، وتختلف التغييرات إذا انتهى الاسم بتاء مربوطة أو ألف أو ياء.","question":"ما اللاحقة الأساسية في اسم النسبة؟","correct":"ياء مشددة","wrong":["تنوين فتح","ألف فارقة","تاء مفتوحة دائمًا"],"practice":"انسب ستة أسماء متنوعة إلى الصيغة الصحيحة مع تبرير التغيير.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"},{"cid":"d12e18e1-365e-4067-bcdc-80363d9c0219","unit":"d4a8c63a-67a5-4ab0-bd64-1d645c5e6d4d","n":8,"title":"العدد والمعدود","passage":"تختلف أحكام العدد والمعدود باختلاف العدد وجنس المعدود وبنيته؛ ففي «ثلاثةُ كتبٍ» يخالف العدد من ثلاثة إلى عشرة المعدود المذكر في الصياغة المعروفة، ويأتي المعدود جمعًا مجرورًا بالإضافة في هذا المثال.","question":"ما المعدود في «ثلاثة كتب»؟","correct":"كتب","wrong":["ثلاثة","من","في"],"practice":"اكتب خمس جمل بأعداد متنوعة واضبط العدد والمعدود مع مرجع نحوي.","old":"DADYOOM_DJ_G12_OFFICIAL_PROGRAMME"}]'::jsonb)
 AS x(cid uuid,unit uuid,n integer,title text,passage text,question text,correct text,wrong text[],practice text,old text)
 LOOP
  SELECT l.id,l.content INTO STRICT target_id,prior
  FROM public.lessons l JOIN public.units u ON u.id=l.unit_id
  JOIN public.grades g ON g.id=u.grade_id
  JOIN public.curricula c ON c.id=g.curriculum_id
  JOIN public.countries co ON co.id=c.country_id
  WHERE co.code='DJ' AND c.id=r.cid
    AND g.grade_number=12 AND u.semester IS NULL AND u.id=r.unit
    AND l.sort_order=r.n AND l.title=r.title AND l.status='published'
  FOR UPDATE OF l;

  SELECT count(*) INTO hasprogress FROM public.student_lesson_progress WHERE lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'DJ_G12_HAS_PROGRESS_%',r.title; END IF;
  SELECT count(*) INTO hasprogress FROM public.lesson_activity_attempts att
    JOIN public.lesson_activities a ON a.id=att.activity_id WHERE a.lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'DJ_G12_HAS_ATTEMPTS_%',r.title; END IF;
  IF char_length(coalesce(prior,''))>=350 THEN RAISE EXCEPTION 'DJ_G12_ALREADY_CONTENT_%',r.title; END IF;
  SELECT count(*) INTO nact FROM public.lesson_activities
    WHERE lesson_id=target_id AND content->>'origin'=r.old AND answer='{}'::jsonb;
  IF nact<>3 THEN RAISE EXCEPTION 'DJ_G12_EXPECTED_3_PLACEHOLDERS_%',r.title; END IF;

  UPDATE public.lessons SET
    content='ضاديوم — إثراء تعليمي أصلي للسنة الرابعة الإعدادية في موريتانيا. هذا ليس نص الكتاب المعتمد ولا تأكيدًا لمطابقة جميع الفصول؛ الاسم مستورد ويلزم تحقق وزاري.'
    ||E'\n\n'||'عنوان الدرس: '||r.title
    ||E'\n\n'||'هدف التعلم: أن يشرح المتعلم فكرة أو قاعدة من المجال، ويحلل قرينة أو شاهدًا صحيح النسبة، ويكتب استجابة جديدة تستند إلى دليل.'
    ||E'\n\n'||'شرح وتطبيق أصلي: '||r.passage
    ||E'\n\n'||'سؤال فهم: '||r.question
    ||E'\n\n'||'تطبيق كتابي مستقل: '||r.practice
    ||E'\n\n'||'التمايز: دعم بقائمة مفردات وخطوات تحليل أساسية، ومستوى متوسط يبرر الاختيار، ومستوى متقدم يقارن بين تفسيرين أو يختبر دقة المصدر. يتولى المعلم مراجعة مهام الكتابة.'
    ||E'\n\n'||'تحذير المصدر: لا تُنسب أمثلة ضاديوم إلى شاعر أو مؤرخ أو نص ديني؛ راجع المصدر المعتمد أولًا.'
    ||E'\n\n'||'المحتوى السابق المحفوظ: '||coalesce(prior,''),
    updated_at=now() WHERE id=target_id;

  UPDATE public.lesson_activities SET
    prompt='اقرأ النص التدريبي المستقل، واستخرج منه الفكرة أو الشاهد الذي تستند إليه الإجابة.',
    content=content||jsonb_build_object('origin','DADYOOM_DJ_G12_ORIGINAL_44_20261009','previousOrigin',r.old,
      'text',r.passage,'notOfficialBook',true,'sourceVerification','pending')
    WHERE lesson_id=target_id AND activity_type='reading'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.question,
    content=content||jsonb_build_object('origin','DADYOOM_DJ_G12_ORIGINAL_44_20261009','previousOrigin',r.old,
       'text',r.question,'notOfficialBook',true,'sourceVerification','pending',
       'options',CASE (r.n%4)
       WHEN 0 THEN jsonb_build_array(r.correct,r.wrong[1],r.wrong[2],r.wrong[3])
       WHEN 1 THEN jsonb_build_array(r.wrong[1],r.correct,r.wrong[2],r.wrong[3])
       WHEN 2 THEN jsonb_build_array(r.wrong[1],r.wrong[2],r.correct,r.wrong[3])
       ELSE jsonb_build_array(r.wrong[1],r.wrong[2],r.wrong[3],r.correct) END),
    answer=jsonb_build_object('correct',r.correct)
    WHERE lesson_id=target_id AND activity_type='multiple_choice'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.practice,
    content=content||jsonb_build_object('origin','DADYOOM_DJ_G12_ORIGINAL_44_20261009','previousOrigin',r.old,
     'text',r.practice,'notOfficialBook',true,'sourceVerification','pending',
     'humanReviewRequired',true)
    WHERE lesson_id=target_id AND activity_type='writing'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  SELECT count(*) INTO nact FROM public.lesson_activities
   WHERE lesson_id=target_id AND content->>'origin'='DADYOOM_DJ_G12_ORIGINAL_44_20261009';
  IF nact<>3 THEN RAISE EXCEPTION 'DJ_G12_ACTIVITY_UPDATE_FAILED_%',r.title; END IF;
 END LOOP;
END $dadyoom$;